export const BYPASS_ROLES = ['Owner', 'Super Admin'];

/** hasPermission for a seeded role — same rule as AuthContext. */
export function permsFor(role) {
  if (BYPASS_ROLES.includes(role)) return () => true;
  const set = new Set(ROLE_PERMISSIONS[role] || []);
  return (module, action) => set.has(`${module}.${action}`) || set.has(`${module}.*`);
}
